use rust_strutil::{count_chars, trim_prefix, words};

#[test]
fn test_count_chars() {
    assert_eq!(count_chars("hello world", 'l'), 3);
    assert_eq!(count_chars("aaa", 'b'), 0);
}

#[test]
fn test_trim_prefix() {
    assert_eq!(trim_prefix("hello world", "hello "), "world");
    assert_eq!(trim_prefix("foobar", "baz"), "foobar");
}

#[test]
fn test_words() {
    assert_eq!(words("the quick brown"), vec!["the", "quick", "brown"]);
    assert_eq!(words(""), Vec::<&str>::new());
}
